import requests
queries=['trophoblast antiphospholipid vitamin D inflammation','trophoblast LMWH sFlt-1 vitamin D','antiphospholipid antibody trophoblast calcitriol','low molecular weight heparin trophoblast sFlt-1 vitamin D']
for q in queries:
 r=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':12,'resultType':'core'},timeout=20)
 print('\nQUERY:',q,'STATUS:',r.status_code)
 for x in r.json().get('resultList',{}).get('result',[]):
  print(x.get('pmid'),x.get('title'),'|',x.get('pubYear'))
  a=x.get('abstractText') or ''
  if a: print(a[:1400].replace('\n',' '))
